import {accountSummary,latestBar,closedAnalytics,dailyTrades,tradeKey,tradePnl,modelStructure,istDay} from './platform-model.js';
import {PlatformStore} from './platform-store.js';
const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(v,d=0)=>Number.isFinite(v)?new Intl.NumberFormat('en-IN',{maximumFractionDigits:d,minimumFractionDigits:d}).format(v):'—';
const money=(v,d=0)=>Number.isFinite(v)?(v<0?'−':'')+'₹'+num(Math.abs(v),d):'—';
const human=v=>String(v||'').replaceAll('_',' ').replace(/^./,s=>s.toUpperCase());
const pct=v=>Number.isFinite(v)?num(v,2)+'%':'—';
const sign=v=>v<0?'negative':'positive';
const metric=(name,value,detail='')=>`<article class="tool-metric"><span>${e(name)}</span><strong>${e(value)}</strong>${detail?`<small>${e(detail)}</small>`:''}</article>`;
const heading=(title,subtitle)=>`<div class="page-heading"><div><p class="eyebrow">PAPER WORKSPACE</p><h1>${title}</h1><p class="subheading">${subtitle}</p></div></div>`;
const opt=(value,label,selected)=>`<option value="${e(value)}" ${value===selected?'selected':''}>${e(label)}</option>`;
export class TradingTools{
 constructor({render=()=>{},toast=()=>{},download=()=>{},navigate=()=>{},pause=()=>{},storage,fetcher=(...a)=>fetch(...a)}={}){Object.assign(this,{render,toast,download,navigate,pause,fetcher});this.store=new PlatformStore(storage);this.meta=null;this.metaPromise=null;this.metaError='';this.model=null;this.modelInput=null;this.modelError='';this.month='';this.reviewDay='';this.reviewKey='';this.reviewDraft=null;this.alertDraft={label:'',type:'engine',threshold:''};this.context=null;}
 setContext(snapshot,automation,mode,controlAllowed=false,operations=null){this.context={snapshot,automation,mode,controlAllowed,operations};try{const added=this.store.observe(snapshot,automation,mode);if(added.length)this.toast(added[0].message);}catch(error){this.store.problem=error.message;}}
 async loadMeta(){if(this.meta)return this.meta;if(!this.metaPromise)this.metaPromise=this.fetcher('platform-config.json',{cache:'no-store'}).then(r=>{if(!r.ok)throw Error('Research parameters unavailable');return r.json();}).then(meta=>{this.meta=meta;this.metaError='';this.render();return meta;}).catch(error=>{this.metaError=error.message;this.metaPromise=null;this.render();throw error;});return this.metaPromise;}
 statusStrip(s){return `<div class="tool-source ${s.fresh?'good':'muted'}"><strong>${s.fresh?'Connected · fresh observed bars':s.connected?'Connected · historical or stale observations':'Saved snapshot · not monitoring live'}</strong><span>Source bar: ${e(s.stamp||'Unavailable')}. ${s.connected?'Heartbeat '+(Number.isFinite(s.heartbeat_seconds)?num(s.heartbeat_seconds)+' seconds ago':'not confirmed')+'.':'Connect the cloud engine from App to monitor your account.'}</span></div>`;}
 links(){return `<div class="tool-shortcuts"><button class="btn" data-action="nav" data-value="options">Options lab</button><button class="btn" data-action="nav" data-value="review">Trade review</button><button class="btn" data-action="show-decisions">Engine activity</button><button class="btn" data-action="nav" data-value="orders">Orders</button><button class="btn" data-action="nav" data-value="mobile">Connect engine</button></div>`;}
 desk(){const {snapshot,automation,mode,controlAllowed}=this.context,s=accountSummary(snapshot,automation,mode),p=s.paper,unread=this.store.unread();
  const connectionProblem=mode.endsWith('disconnected')||s.connected&&(!Number.isFinite(s.heartbeat_seconds)||s.heartbeat_seconds>180||['error','data_error','square_off_waiting_for_data','storage_guard'].includes(automation.state));
  const status=p.halted?'Risk halt':connectionProblem?'Attention required':s.connected?automation.state==='market_closed'?'Market closed':automation.enabled?'Auto paper enabled':'Entries paused':'Snapshot only';
  return `<div class="platform-page">${heading('Risk & alerts','Account visibility, safety limits and device alerts in one place.')}${this.statusStrip(s)}${this.links()}
  <div class="tool-metrics">${metric('Account equity',money(s.marked),'Includes stored unrealised P&L')}${metric('Net closed P&L',money(s.total_pnl),'Lifetime total reported by the engine')}${metric('Closed P&L today',money(s.today_net),s.day+' · IST')}${metric('Current drawdown',pct(s.drawdown_percent),'From the stored account peak')}</div>
  <div class="tool-two-col"><section class="panel tool-card"><div class="tool-card-head"><h2>Risk limits</h2><span class="tag ${p.halted||connectionProblem?'red':'gray'}">${e(status)}</span></div>
  ${[['Per-entry risk budget',money(s.per_entry_budget)],['Daily loss budget (3%)',money(s.daily_loss_budget)],['Remaining daily risk budget',money(s.daily_remaining)],['Open-position risk estimate',money(s.open_risk)],['Entries today / limit',s.daily_entries+' / '+s.entry_limit],['Maximum lots',s.max_lots],['Equity halt threshold',money(s.halt_equity)],['Unrealised P&L (stored mark)',money(s.unrealised)]].map(([label,value])=>`<div class="data-pair"><span>${e(label)}</span><strong>${e(value)}</strong></div>`).join('')}
  <p class="tool-note">Risk estimates are from the options model, not exchange margin or available broker funds. Limits are shown for review; this page does not change the active policy.</p>
  <button class="btn danger" data-action="tools-pause" ${s.connected&&controlAllowed&&automation.enabled?'':'disabled'}>Pause new entries</button><p class="tool-note">Pausing leaves the worker managing existing exits. It does not immediately close a position. ${controlAllowed?'':'A trader account is required for controls.'}</p></section>
  <section class="panel tool-card"><div class="tool-card-head"><h2>Engine and data</h2><span class="tag gray">PAPER ONLY</span></div>
  <div class="tool-check ${connectionProblem?'warn':''}"><strong>${connectionProblem?'Check engine status':s.connected?'Cloud connection available':'Connect to monitor the engine'}</strong><p>Entries ${automation.enabled&&s.connected?'enabled':'not confirmed as enabled'} · worker state ${e(s.connected?human(automation.state):'not confirmed')}. This browser cannot infer server activity from saved records.</p></div>
  <div class="tool-check ${s.fresh?'':'warn'}"><strong>${s.fresh?'Completed market bar is fresh':'No fresh live bar confirmed'}</strong><p>${Number.isFinite(s.bar_age_minutes)?num(s.bar_age_minutes)+' minutes since the last source bar.':'No timestamped bar available.'} Historical bars are expected outside market hours. Price alerts require a fresh bar and heartbeat.</p></div>
  <div class="tool-check"><strong>Configured session · IST</strong><p>Entries 09:45–14:30 · square-off target 15:15 when exit observations are available. No entry is guaranteed; market, volatility and risk filters apply. The engine applies its reviewed exchange calendar; source bars alone do not establish an open session.</p></div>
  <div class="tool-check"><strong>Execution model</strong><p>Observed underlying bars, synthetic option premiums and model fills. No broker connection, live order book, real margin or guaranteed stop execution.</p></div></section></div>
  ${this.context.operations&&s.connected?`<section class="panel tool-card"><div class="tool-card-head"><h2>Server health & recovery</h2><span class="tag ${this.context.operations.ready?'':'amber'}">${this.context.operations.ready?'HEALTHY':'ATTENTION'}</span></div>${[['Engine release',this.context.operations.version||'Unavailable'],['Backup status',human(this.context.operations.backup?.state||'unavailable')],['Last successful backup',this.context.operations.backup?.at||'Not confirmed'],['Off-server recovery',human(this.context.operations.offhost_backup?.state||'not_confirmed')],['Last off-server copy',this.context.operations.offhost_backup?.last_success_at||'Not confirmed'],['Restore verification',this.context.operations.offhost_backup?.restore_verified?'Passed':'Not confirmed'],['Free server disk',Number.isFinite(this.context.operations.storage_free_bytes)?num(this.context.operations.storage_free_bytes/1024**3,2)+' GiB':'Unavailable'],['Execution workers',this.context.operations.execution_workers??'Unavailable'],['Application recovery boot',this.context.operations.assurance?.application_recovery?.verified?'Passed · isolated container':'Not verified for this release'],['Recovery time',Number.isFinite(this.context.operations.assurance?.application_recovery?.recovery_seconds)?this.context.operations.assurance.application_recovery.recovery_seconds+' seconds':'Not measured'],['Seven-day readiness observation',this.context.operations.assurance?.soak?.qualified?'Passed':`Collecting · ${num(this.context.operations.assurance?.soak?.samples??0)} samples`],['Independent security review','Not verified'],['Observed options feed','Not connected']].map(([label,value])=>`<div class="data-pair"><span>${e(label)}</span><strong>${e(value)}</strong></div>`).join('')}<p class="tool-note">Server alerts: ${e((this.context.operations.alerts||[]).map(human).join(', ')||'None reported')}. Health checks worker heartbeat, feed errors, backups and disk headroom. A healthy status is not full production or strategy validation. VM snapshots and off-server copies are reported separately. ${this.context.operations.offhost_backup?.off_host?'The latest off-server copy passed a download and isolated database-restore check.':'Off-server recovery is not currently confirmed by this engine.'} Browser alerts and external email monitoring are separate services.</p></section>`:''}
  ${this.store.problem?`<p class="tool-warning" role="alert">${e(this.store.problem)}</p>`:''}
  <section class="panel tool-card"><div class="tool-card-head"><h2>Device alerts</h2><span class="tag gray">APP OPEN</span></div><p class="tool-note">Alerts evaluate while this app is open. Price, P&L and drawdown alerts require a connected engine; prices also require fresh observations. These are in-app notices, not phone push, email or server-side alerts, and never place orders.</p>
  <form id="alert-builder" class="tool-form tool-alert-form"><label>Alert name<input name="alertLabel" maxlength="80" value="${e(this.alertDraft.label)}" required placeholder="Example: Nifty above my level"></label><label>Condition<select name="alertType">${[['engine','Engine/data attention'],['price_above','Nifty above price'],['price_below','Nifty below price'],['daily_loss','Daily closed loss (%)'],['drawdown','Account drawdown (%)']].map(([v,l])=>opt(v,l,this.alertDraft.type)).join('')}</select></label><label>Price or percentage<input name="alertThreshold" type="number" min="0" max="10000000" step="any" value="${e(this.alertDraft.threshold)}" placeholder="Unused for engine alert"></label><button class="btn primary" type="submit">Add alert</button></form>
  <div class="table-scroll"><table class="data-table"><thead><tr><th>Alert</th><th>Condition</th><th>Threshold</th><th>Status</th><th>Actions</th></tr></thead><tbody>${this.store.data.alerts.length?this.store.data.alerts.map(a=>`<tr><td>${e(a.label)}</td><td>${e(human(a.type))}</td><td>${a.type==='engine'?'—':e(num(a.threshold,2))}</td><td>${a.enabled?'Enabled':'Paused'}</td><td><button class="panel-link" data-action="tools-toggle-alert" data-value="${e(a.id)}">${a.enabled?'Pause':'Enable'}</button> <button class="panel-link" data-action="tools-rearm" data-value="${e(a.id)}">Rearm</button> <button class="panel-link" data-action="tools-remove-alert" data-value="${e(a.id)}">Delete</button></td></tr>`).join(''):'<tr><td colspan="5">No device alerts yet.</td></tr>'}</tbody></table></div></section>
  <section class="panel tool-card"><div class="tool-card-head"><h2>Alert activity ${unread?`<span class="tag amber">${unread} unread</span>`:''}</h2><button class="btn" data-action="tools-ack">Mark read</button></div>${this.store.data.events.length?this.store.data.events.slice(0,30).map(event=>`<article class="tool-event ${event.read?'':'unread'}"><strong>${e(event.label)}</strong><p>${e(event.message)}</p><small>${e(event.at)} · source ${e(event.source_bar||'connection state')}</small></article>`).join(''):'<p class="tool-note">Alerts will appear here when a configured condition is observed. Saved snapshots never trigger price or portfolio alerts.</p>'}</section></div>`;
 }
 ensureModel(){const bar=latestBar(this.context.snapshot);if(!this.modelInput&&bar&&this.meta){this.modelInput={strategy:'bull_put_spread',spot:bar.Close,iv_percent:bar.VIX,lots:1,width:100,timestamp:bar.timestamp,expiry_day:''};this.calculate();}}
 calculate(){try{this.model=modelStructure(this.modelInput,this.meta);this.modelError='';}catch(error){this.model=null;this.modelError=error.message;}}
 options(){const s=accountSummary(this.context.snapshot,this.context.automation,this.context.mode);if(!this.meta&&!this.metaError)this.loadMeta().catch(()=>{});this.ensureModel();const input=this.modelInput||{},model=this.model;
  let chart='';if(model){const ps=model.points,lo=Math.min(0,...ps.map(p=>p[1])),hi=Math.max(0,...ps.map(p=>p[1])),span=hi-lo||1,x=v=>50+(v-ps[0][0])/(ps.at(-1)[0]-ps[0][0])*700,y=v=>220-(v-lo)/span*190;
   chart=`<svg class="payoff-chart" viewBox="0 0 800 265" role="img" aria-label="Theoretical expiry payoff after estimated model fees"><line x1="50" x2="750" y1="${y(0)}" y2="${y(0)}" class="payoff-zero"/><polyline points="${ps.map(([a,b])=>x(a)+','+y(b)).join(' ')}" class="payoff-line" fill="none"/>${[0,.5,1].map(f=>{const i=Math.round(f*(ps.length-1));return `<text x="${x(ps[i][0])}" y="252" text-anchor="middle">${num(ps[i][0])}</text>`;}).join('')}<text x="45" y="20">${money(hi)}</text><text x="45" y="235">${money(lo)}</text><line x1="${x(input.spot)}" x2="${x(input.spot)}" y1="25" y2="220" class="payoff-reference"/></svg>`;
  }
  return `<div class="platform-page">${heading('Options modelling lab','Explore defined-risk structures, theoretical sensitivities and expiry scenarios.')}${this.statusStrip(s)}${this.links()}
  <div class="tool-warning"><strong>Modelled options · not an exchange option chain</strong><p>No live bid/ask, open interest, volume or broker margin is available. Greeks are finite-difference sensitivities of the configured pricing/skew model. Contract size and costs are research assumptions, not a current exchange specification.</p></div>
  ${!this.meta?`<section class="panel tool-card"><p>${e(this.metaError||'Loading research parameters…')}</p>${this.metaError?'<button class="btn" data-action="tools-retry-model">Retry</button>':''}</section>`:`<form id="model-builder" class="panel tool-card tool-form tool-model-form"><label>Structure<select name="modelStrategy">${['bull_put_spread','bear_call_spread','bull_call_spread','bear_put_spread','iron_condor'].map(v=>opt(v,human(v),input.strategy)).join('')}</select></label><label>Reference spot<input name="modelSpot" type="number" min="1000" max="1000000" step="any" value="${e(input.spot)}" required></label><label>Assumed IV (%)<input name="modelIv" type="number" min="1" max="100" step="any" value="${e(input.iv_percent)}" required></label><label>Wings (points)<input name="modelWidth" type="number" min="50" max="500" step="50" value="${e(input.width)}" required></label><label>Lots<input name="modelLots" type="number" min="1" max="5" step="1" value="${e(input.lots)}" required></label><label>Nominal expiry (optional)<input name="modelExpiry" type="date" min="${e(String(input.timestamp||'').slice(0,10))}" value="${e(input.expiry_day)}"></label><div class="tool-form-actions"><button class="btn primary" type="submit">Calculate model</button><button class="btn" type="button" data-action="tools-reference">Use latest observed bar</button></div><p class="tool-note tool-wide">Model reference: ${e(input.timestamp||'Unavailable')}. Leave expiry blank for the configured nominal weekly calendar; holiday adjustments are unverified. Editing a reference price does not change the market feed or submit an order.</p></form>`}
  ${this.modelError?`<p class="tool-warning" role="alert">${e(this.modelError)}</p>`:''}
  ${model?`<div class="tool-metrics">${metric('Maximum expiry profit',money(model.max_profit),'With fixed reference closing-fee estimates')}${metric('Maximum expiry loss',money(model.max_loss),'Defined-risk payoff estimate, not margin')}${metric('Estimated entry fees',money(model.entry_fees),'Assumed '+model.lot_size+' units per lot')}${metric('Break-even levels',model.break_evens.length?model.break_evens.map(v=>num(v,2)).join(' / '):'None within payoff span','After estimated entry and closing fees')}</div>
  <div class="tool-two-col"><section class="panel tool-card"><div class="tool-card-head"><h2>Expiry payoff</h2><span class="tag gray">THEORETICAL</span></div>${chart}<p class="tool-note">Payoff at intrinsic with fixed reference closing-fee estimates on ${e(model.expiry.slice(0,10))}. Fees are estimated at reference premiums and held fixed across scenarios. Excludes actual settlement/exercise charges, price gaps and liquidity. Dashed vertical line marks the reference spot.</p></section>
  <section class="panel tool-card"><h2>Position sensitivities</h2>${[['Delta · ₹ / 1 spot point',model.greeks.delta],['Gamma · ₹ / spot point²',model.greeks.gamma],['Theta · ₹ / calendar day',model.greeks.theta],['Vega · ₹ / 1 IV percentage point',model.greeks.vega]].map(([k,v])=>`<div class="data-pair"><span>${k}</span><strong>${num(v,3)}</strong></div>`).join('')}<p class="tool-note">Aggregated across ${input.lots} lot${input.lots===1?'':'s'} and all legs. Theta is the one-day model change capped at expiry. These sensitivities are estimates, not predicted returns.</p></section></div>
  <section class="panel tool-card"><div class="tool-card-head"><h2>Structure legs</h2><span class="tag ${model.quote.valid?'gray':'amber'}">${model.quote.valid?'Passes model quote filter':'Would be filtered by entry rules'}</span></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Side</th><th>Option</th><th>Strike</th><th>Model mid</th><th>Entry fill</th><th>Delta / unit</th><th>Vega / IV point</th></tr></thead><tbody>${model.legGreeks.map((l,i)=>`<tr><td>${l.qty>0?'BUY':'SELL'}</td><td>${l.cp==='C'?'Call':'Put'}</td><td>${num(l.K)}</td><td>${num(l.price,2)}</td><td>${num(model.quote.fills[i],2)}</td><td>${num(l.delta,4)}</td><td>${num(l.vega,3)}</td></tr>`).join('')}</tbody></table></div></section>
  <div class="tool-two-col"><section class="panel tool-card"><h2>Expiry scenarios</h2><div class="table-scroll"><table class="data-table"><thead><tr><th>Spot move</th><th>Expiry spot</th><th>Model net P&L</th></tr></thead><tbody>${model.scenarios.map(r=>`<tr><td>${r.move>0?'+':''}${r.move}%</td><td>${num(r.spot,2)}</td><td class="${sign(r.expiry_pnl)}">${money(r.expiry_pnl)}</td></tr>`).join('')}</tbody></table></div></section><section class="panel tool-card"><h2>Theoretical premiums near ATM</h2><p class="tool-note">Calculated premiums and deltas only. No orders, bid/ask quotes or open-interest data.</p><div class="table-scroll"><table class="data-table"><thead><tr><th>Strike</th><th>Call</th><th>Call Δ</th><th>Put</th><th>Put Δ</th></tr></thead><tbody>${model.chain.map(r=>`<tr><td>${num(r.strike)}</td><td>${num(r.call.price,2)}</td><td>${num(r.call.delta,3)}</td><td>${num(r.put.price,2)}</td><td>${num(r.put.delta,3)}</td></tr>`).join('')}</tbody></table></div></section></div>`:''}</div>`;
 }
 review(){const p=this.context.snapshot.paper||{},trades=(p.trades||[]).filter(t=>t.status==='closed'&&Number.isFinite(tradePnl(t))),days=dailyTrades(trades),stats=closedAnalytics(trades);
  const month=this.month||days.at(-1)?.day.slice(0,7)||istDay().slice(0,7);this.month=month;const [year,m]=month.split('-').map(Number),count=new Date(Date.UTC(year,m,0)).getUTCDate(),offset=(new Date(Date.UTC(year,m-1,1)).getUTCDay()+6)%7;
  const selected=this.reviewDay.startsWith(month)?this.reviewDay:days.filter(d=>d.day.startsWith(month)).at(-1)?.day||month+'-01';
  const selectedTrades=trades.filter(t=>String(t.exit_date||t.entry?.exit||'').startsWith(selected)),chosen=selectedTrades.find(t=>tradeKey(p,t)===this.reviewKey)||selectedTrades[0];
  const key=chosen?tradeKey(p,chosen):'',note=chosen?(this.reviewDraft?.key===key?this.reviewDraft:this.store.note(p,chosen)):{text:'',tags:''};
  this.selectedTrade=chosen;this.reviewKey=key;
  return `<div class="platform-page">${heading('Trade review','Review forward paper trades, daily outcomes and your own notes.')}${this.links()}<div class="tool-metrics">${metric('Visible closed trades',num(stats.count),'Loaded forward-paper history')}${metric('Win rate',pct(stats.win_rate),'Winners / all visible closed trades')}${metric('Average net / trade',money(stats.average),'After stored model costs')}${metric('Profit factor',stats.profit_factor===null?'Not estimable':num(stats.profit_factor,2),'No finite value when losses are absent')}</div>
  <p class="tool-note">${p.history_window?.has_older_trades?'Older trades exist beyond the loaded history window; these analytics cover visible records only.':'Analytics use the loaded closed paper trades, not backtest trades.'} Notes are device-local and do not alter fills or account P&L.</p>
  <div class="tool-two-col"><section class="panel tool-card"><div class="tool-card-head"><h2>Daily P&L calendar</h2><label class="tool-month">Month<input id="review-month" type="month" value="${e(month)}"></label></div><div class="pnl-calendar" role="group" aria-label="Closed paper P&L calendar">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<span class="calendar-weekday">${d}</span>`).join('')}${Array.from({length:offset},()=>'<span></span>').join('')}${Array.from({length:count},(_,i)=>{const d=month+'-'+String(i+1).padStart(2,'0'),row=days.find(r=>r.day===d);return `<button data-action="tools-day" data-value="${d}" class="calendar-day ${row?sign(row.pnl):''} ${d===selected?'selected':''}" aria-label="${d}: ${row?money(row.pnl)+' from '+row.trades.length+' closed trades':'no closed trades'}"><b>${i+1}</b><span>${row?money(row.pnl):'—'}</span></button>`;}).join('')}</div><p class="tool-note">Closed-trade dates in IST. Blank days mean no loaded closed trade, not a verified exchange holiday.</p></section>
  <section class="panel tool-card"><h2>Review · ${e(selected)}</h2>${selectedTrades.length?`<label class="tool-select-label">Paper trade<select id="review-trade">${selectedTrades.map(t=>opt(tradeKey(p,t),human(t.strategy)+' · '+String(t.entry_date).slice(11,16)+' · '+money(tradePnl(t)),key)).join('')}</select></label><div class="data-pair"><span>Net trade P&L</span><strong class="${sign(tradePnl(chosen))}">${money(tradePnl(chosen),2)}</strong></div><div class="data-pair"><span>Exit reason</span><strong>${e(human(chosen.exit?.exit_reason||chosen.entry?.exit_reason))}</strong></div><form id="review-note-form" class="tool-form"><label>Tags<input name="noteTags" maxlength="120" value="${e(note.tags)}" placeholder="Trend, execution, lesson"></label><label>Review notes<textarea name="noteText" maxlength="2000" rows="6" placeholder="Record the setup, execution and what to review next time.">${e(note.text)}</textarea></label><button class="btn primary" type="submit">Save review note</button></form>`:'<p class="tool-note">No loaded closed trades on this day. Choose a highlighted date.</p>'}</section></div>
  <section class="panel tool-card"><div class="tool-card-head"><h2>Device notes backup</h2><div class="tool-shortcuts"><button class="btn" data-action="tools-export-notes">Export notes</button><button class="btn" data-action="tools-import-notes">Import notes</button></div></div><p class="tool-note">Notes stay in this browser. Export them before clearing browser data, and import on another device to move your journal. Strategy definitions use a separate export in the Workshop.</p><input id="notes-import" type="file" accept=".json,application/json" hidden></section></div>`;
 }
 capture(form){if(form.id==='alert-builder')this.alertDraft={label:form.elements.alertLabel.value,type:form.elements.alertType.value,threshold:form.elements.alertThreshold.value};if(form.id==='model-builder')this.modelInput={...this.modelInput,strategy:form.elements.modelStrategy.value,spot:Number(form.elements.modelSpot.value),iv_percent:Number(form.elements.modelIv.value),width:Number(form.elements.modelWidth.value),lots:Number(form.elements.modelLots.value),expiry_day:form.elements.modelExpiry.value};if(form.id==='review-note-form')this.reviewDraft={key:this.reviewKey,text:form.elements.noteText.value,tags:form.elements.noteTags.value};}
 submit(form){this.capture(form);if(form.id==='alert-builder'){this.store.addAlert(this.alertDraft);this.alertDraft={label:'',type:'engine',threshold:''};this.toast('Device alert added. It checks while the app is open.');}
  if(form.id==='review-note-form'){this.store.saveNote(this.context.snapshot.paper,this.selectedTrade,this.reviewDraft);this.toast('Review note saved on this device.');}
  if(form.id==='model-builder'){this.modelInput={...this.modelInput,strategy:form.elements.modelStrategy.value,spot:Number(form.elements.modelSpot.value),iv_percent:Number(form.elements.modelIv.value),width:Number(form.elements.modelWidth.value),lots:Number(form.elements.modelLots.value),expiry_day:form.elements.modelExpiry.value};this.calculate();}
  this.render();
 }
 async action(action,value){if(action==='tools-remove-alert')this.store.remove(value);if(action==='tools-toggle-alert')this.store.toggle(value);if(action==='tools-rearm')this.store.rearm(value);if(action==='tools-ack')this.store.acknowledge();
  if(action==='tools-pause'){if(!this.context.controlAllowed||!['local','cloud'].includes(this.context.mode))throw Error('Connect a trader account first.');await this.pause();this.toast('New paper entries paused; existing exits remain managed.');}
  if(action==='tools-day'){this.reviewDay=value;this.reviewKey='';this.reviewDraft=null;}
  if(action==='tools-reference'){this.modelInput=null;this.ensureModel();}
  if(action==='tools-retry-model'){this.metaError='';await this.loadMeta();this.ensureModel();}
  if(action==='tools-export-notes')this.download('last-of-our-league-journal.json',JSON.stringify(this.store.exportNotes(),null,2));
  if(action==='tools-import-notes')document.querySelector('#notes-import').click();
  this.render();
 }
}
